insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('bi', '/flags/history/bi-1961.svg', '1961-01-01', '1962-07-01', 'Burundi sous tutelle (Ruanda-Urundi)', 'Burundi under trusteeship (Ruanda-Urundi)', 'Adopté alors que le Burundi relève encore de la tutelle belge du Ruanda-Urundi : le sautoir blanc entre quartiers rouges et verts est déjà en place.', 'Adopted while Burundi was still part of the Belgian trust territory of Ruanda-Urundi: the white saltire between red and green quarters was already there.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('bi', '/flags/history/bi-1966.svg', '1966-07-08', '1966-11-28', 'Royaume du Burundi (Ntare V)', 'Kingdom of Burundi (Ntare V)', 'Dernier drapeau de la monarchie, adopté sous le bref règne de Ntare V, renversé le 28 novembre 1966 par le capitaine Michel Micombero.', 'The monarchy''s last flag, adopted during the short reign of Ntare V, who was overthrown on 28 November 1966 by Captain Michel Micombero.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('bi', '/flags/history/bi-1966-2.svg', '1966-11-28', '1967-06-28', 'Première République (1966-1967)', 'First Republic (1966–1967)', 'Après la proclamation de la République, le tambour royal disparaît du disque central ; seul le sorgho demeure.', 'Once the Republic was proclaimed, the royal drum was removed from the central disc; only the sorghum remained.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('bi', '/flags/history/bi-1967.svg', '1967-06-28', '1982-09-27', 'République du Burundi (1967-1982)', 'Republic of Burundi (1967–1982)', 'Les trois étoiles rouges bordées de vert apparaissent, pour les trois mots de la devise « Unité, Travail, Progrès ». Le drapeau actuel, aux proportions différentes, date de 1982.', 'The three green-edged red stars appeared, one for each word of the motto "Unity, Work, Progress". The current flag, with different proportions, dates from 1982.');
